using System.Text;

namespace OpenTPW;

/// <summary>
/// Which asset-free unit test exercises each opcode (docs/M4-GATE.md, rows vm.opcodes and vm.effect-hooks).
/// <c>ThroughRuntimeEffects</c> entries name a test in which OpenTPW's game effects (<see cref="OriginalObjectEffects"/>,
/// <see cref="VisitorRideScriptEffects"/>) perform the hooked opcode without recording it as unimplemented. The table
/// is generated by <c>RideOpcodeTestMapTests</c> (OPENTPW_OPCODE_TEST_MAP_OUT), which also runs every named test under
/// a <see cref="RideOpcodeRecorder"/> and fails when an entry no longer holds or an exercised opcode is missing.
/// </summary>
public static class RideOpcodeTestMap
{
	public static readonly IReadOnlyList<(Opcode Opcode, string Test, bool ThroughRuntimeEffects)> Entries = new (Opcode, string, bool)[]
	{
		(Opcode.NOP, "RideVMTests.UnknownOpcodesAndRunningOffTheEndStopTheScript", false),
		(Opcode.CRIT_LOCK, "DeterminismTests.DifferentSeedGivesADifferentHash", false),
		(Opcode.CRIT_UNLOCK, "DeterminismTests.DifferentSeedGivesADifferentHash", false),
		(Opcode.COPY, "DeterminismTests.DifferentSeedGivesADifferentHash", false),
		(Opcode.SUB, "RideVMTests.ArithmeticWritesDestinationFirstAndSignExtendsLiterals", false),
		(Opcode.ENDSLICE, "DeterminismTests.DifferentSeedGivesADifferentHash", false),
		(Opcode.GETTIME, "RideVMTests.GetTimeAndTimerCountInMilliseconds", false),
		(Opcode.ADDOBJ, "RideVMTests.DefaultEffectsAreRecordedAsUnimplementedAndReturnZero", false),
		(Opcode.EVENT, "RideVMTests.DefaultEffectsAreRecordedAsUnimplementedAndReturnZero", false),
		(Opcode.FLUSHANIM, "RideVMTests.AnimationDurationsFromEffectsDriveOutputsAndWaits", false),
		(Opcode.TRIGANIM, "RideVMTests.AnimationDurationsFromEffectsDriveOutputsAndWaits", false),
		(Opcode.WAITANIM, "RideVMTests.AnimationDurationsFromEffectsDriveOutputsAndWaits", false),
		(Opcode.RAND, "DeterminismTests.DifferentSeedGivesADifferentHash", false),
		(Opcode.JSR, "RideVMTests.JsrAndReturnAreLifoAndBoundedByTheDeclaredStack", false),
		(Opcode.RETURN, "RideVMTests.JsrAndReturnAreLifoAndBoundedByTheDeclaredStack", false),
		(Opcode.BRANCH, "DeterminismTests.DifferentSeedGivesADifferentHash", false),
		(Opcode.BRANCH_Z, "DeterminismTests.DifferentSeedGivesADifferentHash", false),
		(Opcode.BRANCH_NZ, "DeterminismTests.DifferentSeedGivesADifferentHash", false),
		(Opcode.BRANCH_NV, "RideVMTests.ConditionalBranchesUseZeroAndStrictSignFlags", false),
		(Opcode.BRANCH_PV, "RideVMTests.CmpSubtractsAndBranchNzIsTheInverseOfZero", false),
		(Opcode.NAME, "RideVMTests.LoadsVariablesStringsAndCodeWordBranchTargets", false),
		(Opcode.TEST, "DeterminismTests.DifferentSeedGivesADifferentHash", false),
		(Opcode.CMP, "RideVMTests.ChildScriptsExchangeVariablesWithTheirParent", false),
		(Opcode.PUSH, "RideVMTests.UnknownOpcodesAndRunningOffTheEndStopTheScript", false),
		(Opcode.WAIT, "DeterminismTests.DifferentSeedGivesADifferentHash", false),
		(Opcode.WAIT4ANIM, "RideVMTests.AnimationDurationsFromEffectsDriveOutputsAndWaits", false),
		(Opcode.ADD, "DeterminismTests.DifferentSeedGivesADifferentHash", false),
		(Opcode.DIV, "RideVMTests.ArithmeticWritesDestinationFirstAndSignExtendsLiterals", false),
		(Opcode.MOD, "RideVMTests.ArithmeticWritesDestinationFirstAndSignExtendsLiterals", false),
		(Opcode.TOUR, "RideVMTests.ControllerMutatorsPreserveFlagsDespiteEffectReturnValues", false),
		(Opcode.BUMP, "RideVMTests.BumpDurationCommandsUseOriginalInputForFlagsAndCoastSevenIsNoOp", false),
		(Opcode.COAST, "RideVMTests.BumpDurationCommandsUseOriginalInputForFlagsAndCoastSevenIsNoOp", false),
		(Opcode.LIMBO, "GuestTests.LimboOpcodesHoldGuestsForTheirDurationInSeconds", false),
		(Opcode.UNLIMBO, "GuestTests.LimboOpcodesHoldGuestsForTheirDurationInSeconds", false),
		(Opcode.LIMBOSPACE, "GuestTests.LimboOpcodesHoldGuestsForTheirDurationInSeconds", false),
		(Opcode.SPAWNCHILD, "RideVMTests.ChildScriptsExchangeVariablesWithTheirParent", false),
		(Opcode.SPAWNSOUND, "RideVMTests.ChildScriptsExchangeVariablesWithTheirParent", false),
		(Opcode.REMOVECHILD, "RideVMTests.ChildScriptsExchangeVariablesWithTheirParent", false),
		(Opcode.SETVARINCHILD, "RideVMTests.ChildScriptsExchangeVariablesWithTheirParent", false),
		(Opcode.GETVARINCHILD, "RideVMTests.ChildScriptsExchangeVariablesWithTheirParent", false),
		(Opcode.GETVARINPARENT, "RideVMTests.ChildScriptsExchangeVariablesWithTheirParent", false),
		(Opcode.WALKOFF, "GuestTests.LimboOpcodesHoldGuestsForTheirDurationInSeconds", false),
		(Opcode.WALKGET, "GuestTests.LimboOpcodesHoldGuestsForTheirDurationInSeconds", false),
		(Opcode.FINDSCRIPTRAND, "RideVMTests.NamedScriptsShareVariablesThroughTheWorld", false),
		(Opcode.GETREMOTEVAR, "RideVMTests.NamedScriptsShareVariablesThroughTheWorld", false),
		(Opcode.SETREMOTEVAR, "RideVMTests.NamedScriptsShareVariablesThroughTheWorld", false),
		(Opcode.SETTIMER, "RideVMTests.GetTimeAndTimerCountInMilliseconds", false),
		(Opcode.GETTIMER, "RideVMTests.GetTimeAndTimerCountInMilliseconds", false),
		(Opcode.LIMBO, "GuestTests.LimboOpcodesHoldGuestsForTheirDurationInSeconds", true),
		(Opcode.UNLIMBO, "GuestTests.LimboOpcodesHoldGuestsForTheirDurationInSeconds", true),
		(Opcode.LIMBOSPACE, "GuestTests.LimboOpcodesHoldGuestsForTheirDurationInSeconds", true),
		(Opcode.WALKOFF, "GuestTests.LimboOpcodesHoldGuestsForTheirDurationInSeconds", true),
		(Opcode.WALKGET, "GuestTests.LimboOpcodesHoldGuestsForTheirDurationInSeconds", true),
	};

	/// <summary>The C# initializer lines of <see cref="Entries"/>, for regenerating this file.</summary>
	public static string Format( IEnumerable<(Opcode Opcode, string Test, bool ThroughRuntimeEffects)> entries )
	{
		var builder = new StringBuilder();
		foreach ( var (opcode, test, runtime) in entries )
			builder.Append( $"\t\t(Opcode.{opcode}, \"{test}\", {(runtime ? "true" : "false")}),\n" );
		return builder.ToString();
	}
}
